param(
    [int]$MaxEvents = 10,
    [int[]]$EventIDs = @(20)   # You can pass 20,30 etc.
)

# ================= FILTER =================
$filter = @{
    LogName      = 'System'
    Id           = $EventIDs
    ProviderName = 'Microsoft-Windows-WindowsUpdateClient'
}

# Exclusion pattern (optimized)
$excludePattern = 'Defender Antivirus|Security Intelligence|Windows Malicious Software Removal Tool|-Microsoft\.|MicrosoftWindows\.|Store|App|AppRuntime|Dell|Intel|HP|Hewlett-Packard|Semiconductor|Firmware|Extension|Driver'

# ================= GET EVENTS =================
$events = Get-WinEvent -FilterHashtable $filter -MaxEvents $MaxEvents -ErrorAction SilentlyContinue

if (-not $events) {
    Write-Output "No matching Event ID(s) found"
    exit 0
}

# ================= PROCESS =================
$results = foreach ($event in $events) {

    $msg = $event.Message

    if ($msg -match 'error\s+(0x[0-9A-Fa-f]+)') {

        if (
            # Include only real Windows updates
            $msg -match 'KB\d+' -and
            $msg -match 'Security Update|Cumulative Update|Update for Windows' -and

            # Exclude unwanted noise
            $msg -notmatch $excludePattern
        ) {
            [PSCustomObject]@{
                Key       = "$($matches[1])|$msg"
                ErrorCode = $matches[1]
                Message   = $msg.Trim()
            }
        }
    }
}

# Remove empty
$results = $results | Where-Object { $_ }

if (-not $results) {
    Write-Output "No Error"
    exit 0
}

# ================= GROUP (NO DUPLICATES) =================
$grouped = $results | Group-Object Key

# ================= OUTPUT (INTUNE FIX) =================
$outputLines = @()

foreach ($group in $grouped) {
    $item  = $group.Group[0]
    $count = $group.Count

    $outputLines += "Error $($item.ErrorCode) ($count Times) : -$($item.Message)"
}

# Print ALL lines (important for Intune)
$outputLines -join "`n" | Write-Output

# ================= EXIT =================
if ($grouped.Count -gt 0) {
    exit 1   # Errors found
} else {
    exit 0
}